defmodule BridgeForTeamsWeb.Dashboard.BrandLogos do
  @moduledoc """
  Inline brand logos for third-party integrations (Google, GitHub, Linear,
  Notion, Slack, Feishu/Lark) shown on the onboarding integrations step.

  The SVGs are static compile-time assets (designer-provided, 24×24 viewBox);
  clip paths and ids were stripped so the same logo can appear more than once
  on a page without duplicate-id collisions. Unknown names fall back to a
  neutral dot, mirroring `CoreComponents.icon/1`.
  """
  use Phoenix.Component

  @doc "A brand logo, sized by the wrapping `:class` (the svg fills it)."
  attr(:name, :string, required: true)
  attr(:class, :string, default: "h-5 w-5")

  def brand_logo(assigns) do
    ~H"""
    <span class={["inline-flex shrink-0 items-center justify-center", @class]} aria-hidden="true">
      {Phoenix.HTML.raw(logo_svg(@name))}
    </span>
    """
  end

  # Composio toolkit slugs for Google services share the Google glyph.
  defp logo_svg(slug) when slug in ["gmail", "googlecalendar", "googledrive"],
    do: logo_svg("google")

